WITH unpacked AS (SELECT id, plan, effective_from, currency, TRANSFORM(tier_prices, (p, i) -> ROUND(p * tier_limits[i], 2)) AS tier_revenue_caps, ARRAY_MIN(tier_prices) AS lowest_price, AGGREGATE(tier_prices, CAST(0 AS DOUBLE), (acc, p) -> acc + p, acc -> ROUND(acc / SIZE(tier_prices), 2)) AS avg_tier_price, ELEMENT_AT(tier_prices, 1) AS entry_price FROM price_tiers) SELECT DATE_TRUNC('YEAR', effective_from) AS year_start, AVG(entry_price) AS avg_entry_price, COUNT(DISTINCT id) AS distinct_ids, ROUND(AVG(entry_price), 2) AS avg_entry_price_2, PERCENTILE_APPROX(avg_tier_price, ARRAY(0.25, 0.5, 0.75)) AS avg_tier_price_quartiles, COUNT_IF(plan = 'enterprise') AS enterprise_events FROM unpacked GROUP BY DATE_TRUNC('YEAR', effective_from) ORDER BY avg_entry_price_2 DESC;
